const fs = require('node:fs');
const audit = {launches:0, contexts:0, screenshots:[], active:0, maxActive:0, closed:0};
const save = () => fs.writeFileSync(process.env.MOCK_AUDIT, JSON.stringify(audit));
exports.chromium = {async launch() {
  audit.launches++; save();
  let live = 0;
  return {
    async newContext(profile) {
      audit.contexts++; audit.active++; live++; audit.maxActive=Math.max(audit.maxActive,audit.active); save();
      let closed=false;
      const handlers={};
      let game=false;
      const emit=(text,type='log') => handlers.console?.({text:()=>text,type:()=>type});
      return {
        async newPage() {return {
          on(event,callback) {handlers[event]=callback;},
          async goto(url,options) {
            if(options.timeout !== 30000) throw new Error('Navigation deadline changed');
            game=url.includes('smoke=begin');
            const id=profile.viewport.width===1920?'pc':profile.viewport.width===873?'phone':'ipad';
            if(!game) emit(`Starfire Hearth layout: ${id==='pc'?'wide, pointer':'compact, touch'}, mock`);
            if(game) {
              emit(`Starfire Hearth smoke: new game at turn 2, state ${process.env.MOCK_CASE==='hash'&&id==='ipad'?'000000000000':'911cdd430061'}, 1 save(s)`);
              if(process.env.MOCK_CASE==='error'&&id==='ipad') handlers.pageerror?.(new Error('injected browser error'));
            }
          },
          async waitForFunction(fn,arg,options) {if(options.timeout!==90000) throw new Error('Boot deadline changed'); return true;},
          async waitForTimeout() {},
          async screenshot(options) {
            if(options.timeout!==30000) throw new Error('Capture deadline changed');
            audit.screenshots.push(options.path); save();
            if(process.env.MOCK_CASE==='capture'&&options.path.endsWith('web_ipad_game.png')) throw new Error('injected capture timeout');
          }
        };},
        async close() {if(closed) throw new Error('Context double-close'); closed=true;audit.active--;live--;audit.closed++;save();}
      };
    },
    async close() {if(live) throw new Error('Browser has live contexts'); save();}
  };
}};
